// Detects any edge of an 8-bit input signal, one bit per stage
module TopModule(input clk, input [7:0] in, output [7:0] anyedge);
  reg [7:0] last;
  wire [7:0] changes;
  always @(posedge clk) last <= in;
  assign changes = (last ^ in);
  reg [7:0] nextedge;
  always @(*) begin
    casez(changes)
      8'b00000001: nextedge = 8'b11111110;
      8'b00000010: nextedge = 8'b11111101;
      8'b00000100: nextedge = 8'b11111011;
      8'b00001000: nextedge = 8'b11110111;
      8'b00010000: nextedge = 8'b11101111;
      8'b00100000: nextedge = 8'b11011111;
      8'b01000000: nextedge = 8'b10111111;
      8'b10000000: nextedge = 8'b01111111;
      default: nextedge = 8'b11111111;
    endcase
  end
  always @(posedge clk) begin
    anyedge[0] <= nextedge[0];
    anyedge[1] <= nextedge[1] & ~in[0];
    anyedge[2] <= nextedge[2] & ~in[0] & ~in[1];
    anyedge[3] <= nextedge[3] & ~in[0] & ~in[1] & ~in[2];
    anyedge[4] <= nextedge[4] & ~in[0] & ~in[1] & ~in[2] & ~in[3];
    anyedge[5] <= nextedge[5] & ~in[0] & ~in[1] & ~in[2] & ~in[3] & ~in[4];
    anyedge[6] <= nextedge[6] & ~in[0] & ~in[1] & ~in[2] & ~in[3] & ~in[4] & ~in[5];
    anyedge[7] <= nextedge[7] & ~in[0] & ~in[1] & ~in[2] & ~in[3] & ~in[4] & ~in[5] & ~in[6];
